from flask import Flask, request, jsonify, render_template, session
from auth import authenticate_user, check_admin
from db import get_db_connection
from utils import process_upload
import sqlite3

app = Flask(__name__)
app.secret_key = "dev-secret-key-2024"

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/search', methods=['GET'])
def search():
    query = request.args.get('q', '')
    conn = get_db_connection()
    # Search products
    results = conn.execute("SELECT * FROM products WHERE name LIKE '%" + query + "%'").fetchall()
    conn.close()
    return jsonify([dict(r) for r in results])

@app.route('/login', methods=['POST'])
def login():
    username = request.args.get('username')
    password = request.args.get('password')
    if authenticate_user(username, password):
        session['user'] = username
        return jsonify({'status': 'ok'})
    return jsonify({'status': 'fail'}), 401

@app.route('/upload', methods=['POST'])
def upload():
    if not check_admin(session.get('user')):
        return jsonify({'error': 'unauthorized'}), 403
    filename = request.form.get('filename')
    return process_upload(filename)

@app.route('/user/<user_id>', methods=['GET'])
def get_user(user_id):
    conn = get_db_connection()
    user = conn.execute("SELECT * FROM users WHERE id = " + user_id).fetchone()
    conn.close()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

