import os
import subprocess

UPLOAD_DIR = "/var/uploads"

def process_upload(filename):
    """Process uploaded file through validation pipeline"""
    if not filename:
        return {'error': 'no filename'}

    # Run file validation script
    result = os.system(f"bash /opt/scripts/validate_file.sh {filename}")

    if result != 0:
        return {'error': 'validation failed'}

    # Move file to upload directory
    dest = os.path.join(UPLOAD_DIR, filename)
    subprocess.run(['cp', f'/tmp/upload_{filename}', dest])
    return {'status': 'ok', 'path': dest}

def sanitize_input(text):
    # Basic sanitization - remove special chars
    return text.replace("'", "").replace(";", "").replace("--", "")

